import data from "./apps.json";

export type Host = "pages" | "vercel";
export type App = { date: string; name: string; host: Host; url: string };

// Generated by scripts/fetch-apps.mjs. Dates are when each repo / Vercel project was created.
export const YEAR = data.year; // the current year, i.e. the default view
export const YEARS = data.years as string[]; // every year that has at least one app
export const UPDATED = data.updated;
export const APPS = data.apps as App[];
export const THIS_YEAR = APPS.filter((a) => a.date.startsWith(YEAR));
